//! Move tables and their versioned on-disk bundle (D017, D018).
//!
//! Every table is generated by realising a cube from the coordinate, applying a
//! move, and reading the coordinate back. Nothing is transcribed.
//!
//! `ep8` and `sp` only exist inside `G1`; the eight non-`G1` columns of those
//! two tables hold `u16::MAX` / `u8::MAX` and are undefined. Iterate
//! [`PHASE2_MOVES`] when you need them (D018), never `0..18`.
//!
//! # Bundle format, version 1
//!
//! Little-endian, no padding, one file `cc-tables-v1.bin`:
//!
//! ```text
//! magic      b"CCLT"         4
//! version    u16 = 1         2
//! count      u32 = 6         4
//! payload_len u64            8
//! param_hash u64             8   FNV-1a 64 over CONVENTIONS
//! checksum   u64             8   FNV-1a 64 over the payload
//! directory  6 × (u32 id, u32 rows, u32 cols, u8 width)
//! payload    tables back-to-back in id order
//! ```
//!
//! Ids are `twist=1, flip=2, slice=3, cp=4, ep8=5, sp=6`.

use std::fmt;
use std::fs;
use std::io;
use std::path::{Path, PathBuf};
use std::time::{Duration, Instant};

use color_cube::{Cube, Move, N_MOVES};

use crate::coords;

/// Bundle magic, `b"CCLT"`.
pub const MAGIC: [u8; 4] = *b"CCLT";

/// On-disk format version.
pub const FORMAT_VERSION: u16 = 1;

/// Bundle file name inside the table directory.
pub const BUNDLE_FILE: &str = "cc-tables-v1.bin";

/// The ten moves that keep a `G1` cube inside `G1` (D018).
///
/// `U, U2, U', D, D2, D', R2, L2, F2, B2`.
pub const PHASE2_MOVES: [usize; 10] = [0, 1, 2, 9, 10, 11, 4, 7, 13, 16];

/// Table ids, in payload order.
pub const ID_TWIST: u32 = 1;
/// Table id for `move_flip`.
pub const ID_FLIP: u32 = 2;
/// Table id for `move_slice`.
pub const ID_SLICE: u32 = 3;
/// Table id for `move_cp`.
pub const ID_CP: u32 = 4;
/// Table id for `move_ep8`.
pub const ID_EP8: u32 = 5;
/// Table id for `move_sp`.
pub const ID_SP: u32 = 6;

/// Rows in `move_twist`.
pub const TWIST_ROWS: usize = 2187;
/// Rows in `move_flip`.
pub const FLIP_ROWS: usize = 2048;
/// Rows in `move_slice`.
pub const SLICE_ROWS: usize = 495;
/// Rows in `move_cp`.
pub const CP_ROWS: usize = 40_320;
/// Rows in `move_ep8`.
pub const EP8_ROWS: usize = 40_320;
/// Rows in `move_sp`.
pub const SP_ROWS: usize = 24;

/// The frozen conventions literal hashed into every bundle.
///
/// Changing any byte of this literal invalidates every cached table file. Keep
/// it in one place so the parameter hash actually means something.
pub const CONVENTIONS: &str = concat!(
    "cc-livive-net coordinate tables\n",
    "format=1\n",
    "twist=sum(co[i]*3^i,i=0..6);co[7]=(3-sum%3)%3;range=0..2186\n",
    "flip=sum(eo[i]*2^i,i=0..10);eo[11]=sum%2;range=0..2047\n",
    "slice=C(p0,1)+C(p1,2)+C(p2,3)+C(p3,4);pieces=FR,FL,BL,BR=8..11;solved=494\n",
    "cp=lehmer8(0..40319)\n",
    "ep8=lehmer8(ep[0..8]);range=0..40319;g1=only\n",
    "sp=lehmer4(ep[8..12]-8);range=0..23;g1=only\n",
    "faces=URFDLB;moves=U,U2,U',R,R2,R',F,F2,F',D,D2,D',L,L2,L',B,B2,B'\n",
    "ids=twist:1:u16,flip:2:u16,slice:3:u16,cp:4:u16,ep8:5:u16,sp:6:u8\n",
    "phase2_moves=0,1,2,9,10,11,4,7,13,16;ep8_sentinel=65535;sp_sentinel=255\n",
);

/// All six move tables, flat and row-major, indexed `coord * 18 + move`.
#[derive(Clone, Debug, PartialEq, Eq)]
pub struct TableBundle {
    /// `2187 × 18` twist transitions.
    pub move_twist: Vec<u16>,
    /// `2048 × 18` flip transitions.
    pub move_flip: Vec<u16>,
    /// `495 × 18` slice transitions.
    pub move_slice: Vec<u16>,
    /// `40320 × 18` corner-permutation transitions.
    pub move_cp: Vec<u16>,
    /// `40320 × 18` U/D-edge transitions; non-`G1` columns are `u16::MAX`.
    pub move_ep8: Vec<u16>,
    /// `24 × 18` slice-permutation transitions; non-`G1` columns are `u8::MAX`.
    pub move_sp: Vec<u8>,
}

/// Per-table generation time, in table id order.
#[derive(Clone, Copy, Debug)]
pub struct TableTiming {
    /// Table id (`1..=6`).
    pub id: u32,
    /// Wall time spent generating the table.
    pub elapsed: Duration,
}

impl TableBundle {
    /// Byte size of each table's payload, in table id order.
    #[must_use]
    pub fn payload_sizes(&self) -> [usize; 6] {
        [
            self.move_twist.len() * 2,
            self.move_flip.len() * 2,
            self.move_slice.len() * 2,
            self.move_cp.len() * 2,
            self.move_ep8.len() * 2,
            self.move_sp.len(),
        ]
    }
}

/// Why a bundle could not be loaded.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum TablesError {
    /// The bundle file does not exist.
    Missing,
    /// The file exists but is unreadable or fails validation.
    TableCorrupt,
}

impl fmt::Display for TablesError {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            TablesError::Missing => f.write_str("table bundle is missing"),
            TablesError::TableCorrupt => f.write_str("table bundle is corrupt"),
        }
    }
}

impl std::error::Error for TablesError {}

/// Generates all six tables.
#[must_use]
pub fn generate() -> TableBundle {
    generate_with_timings().0
}

/// Generates all six tables and records how long each one took.
#[must_use]
pub fn generate_with_timings() -> (TableBundle, [TableTiming; 6]) {
    let started = Instant::now();
    let move_twist = generate_twist();
    let t0 = started.elapsed();

    let started = Instant::now();
    let move_flip = generate_flip();
    let t1 = started.elapsed();

    let started = Instant::now();
    let move_slice = generate_slice();
    let t2 = started.elapsed();

    let started = Instant::now();
    let move_cp = generate_cp();
    let t3 = started.elapsed();

    let started = Instant::now();
    let move_ep8 = generate_ep8();
    let t4 = started.elapsed();

    let started = Instant::now();
    let move_sp = generate_sp();
    let t5 = started.elapsed();

    let bundle = TableBundle {
        move_twist,
        move_flip,
        move_slice,
        move_cp,
        move_ep8,
        move_sp,
    };
    let timings = [
        TableTiming {
            id: ID_TWIST,
            elapsed: t0,
        },
        TableTiming {
            id: ID_FLIP,
            elapsed: t1,
        },
        TableTiming {
            id: ID_SLICE,
            elapsed: t2,
        },
        TableTiming {
            id: ID_CP,
            elapsed: t3,
        },
        TableTiming {
            id: ID_EP8,
            elapsed: t4,
        },
        TableTiming {
            id: ID_SP,
            elapsed: t5,
        },
    ];
    (bundle, timings)
}

fn generate_twist() -> Vec<u16> {
    let mut table = Vec::with_capacity(TWIST_ROWS * N_MOVES);
    let mut base = Cube::SOLVED;
    for value in 0..TWIST_ROWS {
        base.set_corner_twist(value as u16);
        for index in 0..N_MOVES {
            let mut cube = base;
            cube.apply(Move(index as u8));
            table.push(cube.corner_twist());
        }
    }
    table
}

fn generate_flip() -> Vec<u16> {
    let mut table = Vec::with_capacity(FLIP_ROWS * N_MOVES);
    let mut base = Cube::SOLVED;
    for value in 0..FLIP_ROWS {
        base.set_edge_flip(value as u16);
        for index in 0..N_MOVES {
            let mut cube = base;
            cube.apply(Move(index as u8));
            table.push(cube.edge_flip());
        }
    }
    table
}

fn generate_slice() -> Vec<u16> {
    let mut table = Vec::with_capacity(SLICE_ROWS * N_MOVES);
    let mut base = Cube::SOLVED;
    for value in 0..SLICE_ROWS {
        base.set_slice_combination(value as u16);
        for index in 0..N_MOVES {
            let mut cube = base;
            cube.apply(Move(index as u8));
            table.push(cube.slice_combination());
        }
    }
    table
}

fn generate_cp() -> Vec<u16> {
    let mut table = Vec::with_capacity(CP_ROWS * N_MOVES);
    let mut base = Cube::SOLVED;
    for value in 0..CP_ROWS {
        coords::set_cp(&mut base, value as u16);
        for index in 0..N_MOVES {
            let mut cube = base;
            cube.apply(Move(index as u8));
            table.push(coords::cp_rank(&cube));
        }
    }
    table
}

fn generate_ep8() -> Vec<u16> {
    let mut table = vec![u16::MAX; EP8_ROWS * N_MOVES];
    let mut base = Cube::SOLVED;
    for value in 0..EP8_ROWS {
        coords::set_ep8(&mut base, value as u16);
        for &index in &PHASE2_MOVES {
            let mut cube = base;
            cube.apply(Move(index as u8));
            table[value * N_MOVES + index] = coords::ep8_rank(&cube);
        }
    }
    table
}

fn generate_sp() -> Vec<u8> {
    let mut table = vec![u8::MAX; SP_ROWS * N_MOVES];
    let mut base = Cube::SOLVED;
    for value in 0..SP_ROWS {
        coords::set_sp(&mut base, value as u16);
        for &index in &PHASE2_MOVES {
            let mut cube = base;
            cube.apply(Move(index as u8));
            table[value * N_MOVES + index] = coords::sp_rank(&cube) as u8;
        }
    }
    table
}

/// Encodes a bundle into the version-1 byte format.
#[must_use]
pub fn encode(bundle: &TableBundle) -> Vec<u8> {
    let sizes = bundle.payload_sizes();
    let payload_len: usize = sizes.iter().sum();
    let mut out = Vec::with_capacity(HEADER_LEN + DIRECTORY_LEN + payload_len);

    out.extend_from_slice(&MAGIC);
    out.extend_from_slice(&FORMAT_VERSION.to_le_bytes());
    out.extend_from_slice(&(6u32).to_le_bytes());
    out.extend_from_slice(&(payload_len as u64).to_le_bytes());
    out.extend_from_slice(&fnv1a64(CONVENTIONS.as_bytes()).to_le_bytes());
    out.extend_from_slice(&0u64.to_le_bytes()); // checksum placeholder

    let entries = table_entries();
    for (id, rows, cols, width) in entries {
        out.extend_from_slice(&id.to_le_bytes());
        out.extend_from_slice(&rows.to_le_bytes());
        out.extend_from_slice(&cols.to_le_bytes());
        out.push(width);
    }

    let payload_start = out.len();
    push_u16(&mut out, &bundle.move_twist);
    push_u16(&mut out, &bundle.move_flip);
    push_u16(&mut out, &bundle.move_slice);
    push_u16(&mut out, &bundle.move_cp);
    push_u16(&mut out, &bundle.move_ep8);
    out.extend_from_slice(&bundle.move_sp);
    debug_assert_eq!(out.len() - payload_start, payload_len);

    let checksum = fnv1a64(&out[payload_start..]);
    out[CHECKSUM_OFFSET..CHECKSUM_OFFSET + 8].copy_from_slice(&checksum.to_le_bytes());
    out
}

/// Writes a bundle atomically into `directory` and returns the file path.
///
/// A temporary file in the same directory is renamed over the target, so a
/// concurrent reader never sees a partial bundle.
///
/// # Errors
///
/// Returns the underlying I/O error if the directory cannot be created or the
/// file cannot be written.
pub fn write(directory: &Path, bundle: &TableBundle) -> io::Result<PathBuf> {
    fs::create_dir_all(directory)?;
    let target = directory.join(BUNDLE_FILE);
    let temp = directory.join(format!(".{BUNDLE_FILE}.{}.tmp", std::process::id()));
    fs::write(&temp, encode(bundle))?;
    fs::rename(&temp, &target)?;
    Ok(target)
}

/// Loads the bundle from `directory`.
///
/// # Errors
///
/// [`TablesError::Missing`] when the file is absent, [`TablesError::TableCorrupt`]
/// for any magic, version, hash, checksum or dimension failure.
pub fn load(directory: &Path) -> Result<TableBundle, TablesError> {
    let path = directory.join(BUNDLE_FILE);
    let data = match fs::read(&path) {
        Ok(data) => data,
        Err(error) if error.kind() == io::ErrorKind::NotFound => return Err(TablesError::Missing),
        Err(_) => return Err(TablesError::TableCorrupt),
    };
    decode(&data)
}

/// Decodes a version-1 bundle.
///
/// # Errors
///
/// [`TablesError::TableCorrupt`] on any structural or content mismatch.
pub fn decode(data: &[u8]) -> Result<TableBundle, TablesError> {
    if data.len() < HEADER_LEN + DIRECTORY_LEN {
        return Err(TablesError::TableCorrupt);
    }
    if data[..4] != MAGIC {
        return Err(TablesError::TableCorrupt);
    }
    let version = u16::from_le_bytes([data[4], data[5]]);
    if version != FORMAT_VERSION {
        return Err(TablesError::TableCorrupt);
    }
    let count = u32::from_le_bytes([data[6], data[7], data[8], data[9]]);
    if count != 6 {
        return Err(TablesError::TableCorrupt);
    }
    let payload_len = read_u64(data, 10);
    let param_hash = read_u64(data, 18);
    let checksum = read_u64(data, 26);
    if param_hash != fnv1a64(CONVENTIONS.as_bytes()) {
        return Err(TablesError::TableCorrupt);
    }

    let expected = [
        (ID_TWIST, TWIST_ROWS, N_MOVES, 2u8),
        (ID_FLIP, FLIP_ROWS, N_MOVES, 2),
        (ID_SLICE, SLICE_ROWS, N_MOVES, 2),
        (ID_CP, CP_ROWS, N_MOVES, 2),
        (ID_EP8, EP8_ROWS, N_MOVES, 2),
        (ID_SP, SP_ROWS, N_MOVES, 1),
    ];
    let mut offset = HEADER_LEN;
    let mut sizes = [0usize; 6];
    for (slot, want) in expected.iter().enumerate() {
        if offset + 13 > data.len() {
            return Err(TablesError::TableCorrupt);
        }
        let id = u32::from_le_bytes([
            data[offset],
            data[offset + 1],
            data[offset + 2],
            data[offset + 3],
        ]);
        let rows = u32::from_le_bytes([
            data[offset + 4],
            data[offset + 5],
            data[offset + 6],
            data[offset + 7],
        ]);
        let cols = u32::from_le_bytes([
            data[offset + 8],
            data[offset + 9],
            data[offset + 10],
            data[offset + 11],
        ]);
        let width = data[offset + 12];
        if (id, rows as usize, cols as usize, width) != *want {
            return Err(TablesError::TableCorrupt);
        }
        sizes[slot] = rows as usize * cols as usize * width as usize;
        offset += 13;
    }

    let payload_start = HEADER_LEN + DIRECTORY_LEN;
    if data.len() != payload_start.saturating_add(payload_len as usize) {
        return Err(TablesError::TableCorrupt);
    }
    let payload = &data[payload_start..];
    if fnv1a64(payload) != checksum {
        return Err(TablesError::TableCorrupt);
    }

    let mut cursor = 0;
    let move_twist = read_u16_table(payload, &mut cursor, sizes[0]);
    let move_flip = read_u16_table(payload, &mut cursor, sizes[1]);
    let move_slice = read_u16_table(payload, &mut cursor, sizes[2]);
    let move_cp = read_u16_table(payload, &mut cursor, sizes[3]);
    let move_ep8 = read_u16_table(payload, &mut cursor, sizes[4]);
    let move_sp = payload[cursor..cursor + sizes[5]].to_vec();

    Ok(TableBundle {
        move_twist,
        move_flip,
        move_slice,
        move_cp,
        move_ep8,
        move_sp,
    })
}

/// Resolves the bundle directory, honouring `COLOR_CUBE_TABLES` (a directory).
#[must_use]
pub fn default_directory() -> PathBuf {
    std::env::var_os("COLOR_CUBE_TABLES").map_or_else(|| PathBuf::from("./tables"), PathBuf::from)
}

const HEADER_LEN: usize = 4 + 2 + 4 + 8 + 8 + 8;
const DIRECTORY_LEN: usize = 6 * 13;
const CHECKSUM_OFFSET: usize = 26;

fn table_entries() -> [(u32, u32, u32, u8); 6] {
    [
        (ID_TWIST, TWIST_ROWS as u32, N_MOVES as u32, 2),
        (ID_FLIP, FLIP_ROWS as u32, N_MOVES as u32, 2),
        (ID_SLICE, SLICE_ROWS as u32, N_MOVES as u32, 2),
        (ID_CP, CP_ROWS as u32, N_MOVES as u32, 2),
        (ID_EP8, EP8_ROWS as u32, N_MOVES as u32, 2),
        (ID_SP, SP_ROWS as u32, N_MOVES as u32, 1),
    ]
}

fn push_u16(out: &mut Vec<u8>, values: &[u16]) {
    for &value in values {
        out.extend_from_slice(&value.to_le_bytes());
    }
}

fn read_u16_table(payload: &[u8], cursor: &mut usize, bytes: usize) -> Vec<u16> {
    let end = *cursor + bytes;
    let (pairs, _) = payload[*cursor..end].as_chunks::<2>();
    let table = pairs.iter().map(|pair| u16::from_le_bytes(*pair)).collect();
    *cursor = end;
    table
}

fn read_u64(data: &[u8], offset: usize) -> u64 {
    let mut bytes = [0u8; 8];
    bytes.copy_from_slice(&data[offset..offset + 8]);
    u64::from_le_bytes(bytes)
}

/// FNV-1a, 64-bit.
fn fnv1a64(data: &[u8]) -> u64 {
    let mut hash = 0xcbf2_9ce4_8422_2325u64;
    for &byte in data {
        hash ^= u64::from(byte);
        hash = hash.wrapping_mul(0x0000_0100_0000_01b3);
    }
    hash
}
